use std::fs

fn main() {
    let limit: int = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut counts: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    let mut c: int = 0
    let mut l: int = 0
    let mut i: int = 0
    while i <= limit {
        if i >= 2 && sieve[i] {
            c += 1
            l = i
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        counts[i] = c
        last[i] = l
        i += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut out: Vec<string> = []
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = s.parse::<int>().unwrap_or(0)
        if last[n] == 0 {
            out.push("0 none")
        } else {
            out.push("${counts[n]} ${last[n]}")
        }
    }
    println(out.join("\n"))
}

